package shop

type Item struct {
	Name     string
	PriceCts int
	Qty      int
}

func Total(items []Item, discountPercent int) int {
	total := 0
	for _, it := range items {
		total += it.PriceCts * it.Qty
	}
	return total + total*discountPercent/100
}
package shop

import "testing"

func TestTotal(t *testing.T) {
	items := []Item{{"pen", 150, 2}, {"book", 1000, 1}}
	if got := Total(items, 0); got != 1300 {
		t.Errorf("no discount: got %d, want 1300", got)
	}
	if got := Total(items, 10); got != 1170 {
		t.Errorf("10%% discount: got %d, want 1170", got)
	}
}
package shop

import "sort"

func Mean(xs []int) float64 {
	if len(xs) == 0 {
		return 0
	}
	sum := 0
	for _, x := range xs {
		sum += x
	}
	return float64(sum / len(xs))
}

func Median(xs []float64) float64 {
	if len(xs) == 0 {
		return 0
	}
	s := append([]float64(nil), xs...)
	sort.Float64s(s)
	n := len(s)
	if n%2 == 1 {
		return s[n/2]
	}
	return (s[n/2-1] + s[n/2]) / 2
}
package shop

import "testing"

func TestMean(t *testing.T) {
	if got := Mean([]int{1, 2}); got != 1.5 {
		t.Errorf("Mean([1 2]) = %v, want 1.5", got)
	}
	if got := Mean(nil); got != 0 {
		t.Errorf("Mean(nil) = %v, want 0", got)
	}
}

func TestMedian(t *testing.T) {
	if got := Median([]float64{3, 1, 2}); got != 2 {
		t.Errorf("odd: got %v, want 2", got)
	}
	if got := Median([]float64{4, 1, 3, 2}); got != 2.5 {
		t.Errorf("even: got %v, want 2.5", got)
	}
}
package shop

import "strings"

func WordCount(s string) int {
	return len(strings.Fields(s))
}

func Truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n-1] + "…"
}
package shop

import "testing"

func TestWordCount(t *testing.T) {
	if got := WordCount("  one two\tthree\n"); got != 3 {
		t.Errorf("got %d, want 3", got)
	}
}

func TestTruncate(t *testing.T) {
	cases := []struct {
		in   string
		n    int
		want string
	}{
		{"hello", 5, "hello"},
		{"hello world", 5, "hell…"},
		{"привет мир", 6, "приве…"},
	}
	for _, c := range cases {
		if got := Truncate(c.in, c.n); got != c.want {
			t.Errorf("Truncate(%q, %d) = %q, want %q", c.in, c.n, got, c.want)
		}
	}
}

